def normalize_expense(expense):
    normalized_expense = {
        'vendor': expense.get('vendor'),
        'date': expense.get('date'),
        'total': expense.get('total'),
        'line_items': expense.get('line_items', [])
    }
    return normalized_expense

def validate_document_fields(document):
    required_fields = ['vendor', 'date', 'total', 'line_items']
    for field in required_fields:
        if field not in document:
            return False
    return True

from azure.ai.documentintelligence.models import AnalyzeDocumentRequest, DocumentType

def create_analyze_request(document_path, document_type):
    with open(document_path, 'rb') as document_file:
        return AnalyzeDocumentRequest(document=document_file, model_id=document_type)

def summarize_invoice_fields(invoice):
    summary = {
        'vendor': invoice.get('vendor'),
        'date': invoice.get('date'),
        'total': invoice.get('total'),
        'line_items': invoice.get('line_items', [])
    }
    return summary
